SELECT i.id, i.product_id AS productId, i.product_name AS productName, i.product_type AS productType, i.sku_id AS skuId, i.sku_attribute AS skuAttribute, i.sku_value AS skuValue, i.current_stock AS currentStock, i.min_stock AS minStock, i.sales, i.create_time AS createTime, i.last_update_time AS lastUpdateTime FROM inventory i JOIN product p ON i.product_id = p.product_id WHERE 1=1 AND p.seller_id = #{sellerId}
AND i.product_type = #{productType}
AND i.current_stock <= 0
AND i.current_stock > 0 AND i.current_stock < i.min_stock
AND i.current_stock >= i.min_stock
AND i.product_name LIKE CONCAT('%', #{keyword}, '%')

SELECT COUNT(1) FROM inventory i JOIN product p ON i.product_id = p.product_id WHERE 1=1 AND p.seller_id = #{sellerId}
AND i.product_type = #{productType}
AND i.current_stock <= 0
AND i.current_stock > 0 AND i.current_stock < i.min_stock
AND i.current_stock >= i.min_stock
AND i.product_name LIKE CONCAT('%', #{keyword}, '%')
